INSERT INTO `quest_offer_reward_locale` (`ID`,`locale`,`RewardText`,`VerifiedBuild`) VALUES
(79097,'ruRU','Спасибо, $n. Благодаря тебе архивы наших знаний растут.\r\n\r\nЕсли найдешь другие чародейские труды, которых не хватает в библиотеке, приноси их мне.',70338),
(91741,'ruRU','Эй, откуда у тебя это? Она должна стоять на полке! О нет, кобольды опять принялись воровать мои книги. Наверняка пытаются их съесть!\r\n\r\nСпасибо, что $gвернул:вернула; эту книгу, но как же мне быть с остатками пропавшей коллекции?',70338),
(92124,'ruRU','Да, я уже в курсе. Сто раз предупреждал брата Пакстона, что кобольды роют туннели под аббатством.\r\n\r\nПохоже, они забрали много книг. Некоторые полки опустошены полностью. Узнай у брата Пакстона, что он хочет сделать по этому поводу.\r\n\r\nКстати, пока ты еще здесь, не хочешь поговорить о ремеслах? Я с радостью отвечу на любые вопросы и расскажу, где найти местных наставников.',70338),
(92460,'ruRU','Приветствую, $n! Для меня честь вручить тебе эту реликвию к совершеннолетию. В тебе скрыт огромный потенциал, который послужит шен\'дорай. У нашего народа сложная история, и мы пережили много горя и гонений.\r\n\r\nСегодня в твои руки переходит одна из реликвий, когда-то принадлежавших твоим предшественникам. Однажды, когда твой прах будет развеян, ее получит кто-то еще, и традиция будет продолжена.\r\n\r\nДержи ее и помни: ветер из дома всегда будет с тобой, где бы ты ни $gстранствовал:странствовала;.',70338),
(92461,'ruRU','Спасибо за помощь Зефрису, |3-6($c).\r\n\r\nОбычно лисвены смирные, но все звери на Зефрисе чуют, когда магия ветров выходит из равновесия. И если ничего с этим не делать, они могут начать вести себя опасно и непредсказуемо.',70338),
(92462,'ruRU','Судя по тому, что ты с ног до головы $gпокрыт:покрыта; кусками насекомых, ос и правда было немало.',70338),
(92463,'ruRU','Чудесно, $n. Если с искательством приключений дело не выгорит, из тебя выйдет прекрасный следопыт.',70338),
(92464,'ruRU','Тебя прислал Рориан? Прекрасно. Мне понадобится твоя помощь.',70338),
(92465,'ruRU','Мне больно проливать в роще кровь шен\'дорай, но мы должны делать то, что необходимо.',70338),
(92469,'ruRU','Вести мрачные, но, увы, ожидаемые. Мы уже давно знали о действиях сектантов, но лишь наблюдали за ними издалека. Однако то, что они разгневали духов ветра у стоячих камней, – это уже слишком.\r\n\r\nТы $gоказал:оказала; Тендалской роще тяжелую, но необходимую услугу, $n. Благодарю.',70338),
(92470,'ruRU','Замечательно. Ты $gодолел:одолела; диких зверей и бесчестных сектантов. Что-то в тебе определенно есть, но скоро путь уведет тебя из относительно безопасной деревни Тендал.',70338),
(92471,'ruRU','Рориан много рассказывал о тебе. Ты, скорее всего, меня не знаешь, но я принадлежу к Совету старейшин острова Зефрис. Я читаю потоки ветра в Тендалской роще, а еще оцениваю молодых шен\'дорай вроде тебя, готовых стать взрослыми.\r\n\r\nСкажи, $gготов:готова; ли ты сделать следующий шаг и послужить острову Зефрис?',70338),
(92472,'ruRU','Тебя, значит, прислала Эфин? Скажу честно: на мой взгляд, толку от тебя будет немного, но деревня Шен\'дар не станет отказываться от добровольных помощников. Тем более, если их прислала сама старейшина Эфин.',70338),
(92473,'ruRU','Молодцом, |3-6($c). Следопыты Рощи у тебя в долгу.',70338),
(92474,'ruRU','Да сколько раз мне говорить Мириаал, чтобы не подбивала других применять наши врожденные способности для всякой ерунды?\r\n\r\nВпрочем, небольшая тренировка в относительно безопасной деревне может быть... полезной.\r\n\r\nНо в будущем советую применять способности осмотрительно. Израсходуешь магию, а потом не сможешь воспользоваться ей, когда она будет действительно нужна.',70338),
(92485,'ruRU','Флора и фауна острова Зефрис – это целая палитра яркой, безудержной жизни. Чтобы в природе была гармония, требуется постоянно поддерживать все в равновесии, и храним это равновесие мы, друиды. Я вижу в тебе отличные задатки, но этот путь труден, и тебе понадобится наставник, чтобы ты $gсмог:смогла; познать тайны клыка, когтя, пера и ветви.\r\n\r\nПоговори со мной вновь, когда будешь $gготов:готова; сделать следующий шаг.',70338),
(92514,'ruRU','Значит, ты $gпоговорил:поговорила; с Иллайей? Отлично. Отношения у Высшего ордена и Ваятелей ветра сейчас напряженные, но здесь, в Шен\'даре, они держат свой конфликт в рамках. Всем известно, что у нас есть дела поважнее.\r\n\r\nТак, с этим мы закончили... Похоже, ты ищешь себе занятие. У нас тут проблема с бандитами – надеюсь, ты согласишься помочь.',70245),
(92515,'ruRU','Никто ведь не обещал, что работа не будет грязной, верно?',70338),
(92516,'ruRU','Отличная работа – и быстрая. Неплохо, неплохо.',70338),
(92517,'ruRU','С бандитами покончено, и у нас стало одной проблемой меньше. Но, признаться, теперь меня беспокоит, что выжившие бандиты присоединятся к культу, который и без того разрастается тревожными темпами.\r\n\r\nВпрочем, нам важна каждая победа.',70338),
(92528,'ruRU','Сама Лортуна была там? Она же лидер этой проклятой секты!\r\n\r\nЕсли они собираются наступать на деревню Шен\'дар и западную сторожевую башню, мы должны подготовиться. Но вот что странно... Зачем им сторожевая башня?\r\n\r\nС деревней-то все ясно, но башня... Да, это пост наблюдения, но не самый стратегически важный.\r\n\r\nВ любом случае мы будем готовы. Пусть узнают, что жителей нагорья не так легко застать врасплох, как они думают.',70338),
(92529,'ruRU','Кто тут у нас? $gНовый последователь, желающий:Новая последовательница, желающая; служить Владыке Ветра? Значит, тебя прислала Сания? Воистину четыре ветра ныне благоволят нам!\r\n\r\nМы рады всем, кто ищет благословения Ал\'акира.',70338),
(92544,'ruRU','Как же мне хотелось бросить дежурство и присоединиться к тебе. Надеюсь, эти негодяи все поняли и скоро уберутся восвояси.\r\n\r\nСпасибо, |3-6($c). Следопыты Тендалской рощи благодарны тебе.',70338),
(92550,'ruRU','Слава ветрам, ты $gвернулся:вернулась;!\r\n\r\nСания Серебряный Поток буквально только что ускользнула из деревни – наверняка испугалась того, что жители готовят оружие.\r\n\r\nТы $gоказал:оказала; неоценимую помощь деревне Шен\'дар. Мы все перед тобой в долгу. Если сектанты вернутся на нагорье, они поймут, что мы не такая уж и легкая мишень.\r\n\r\nДа направят тебя ветра, $n.',70338),
(92551,'ruRU','Замечательно! Без регулярных поставок припасов нам приходилось несладко. Мы с констеблем позаботимся о том, чтобы это досталось наиболее нуждающимся.',70338),
(92553,'ruRU','Эти яйца непросто раздобыть, но, о ветер, какие же они вкусные, если пожарить их в сале медверы!\r\n\r\nЕсли у тебя есть время и ты любишь готовить, могу дать тебе несколько советов. Я готов начать обучение хоть сейчас – только скажи.',70338),
(92595,'ruRU','Думаю, теперь ты понимаешь, как важен долг Ваятелей ветра. Мы должны ценить каждого одаренного небесным взором, если хотим, чтобы духи ветров вновь внимали нам.\r\n\r\nАл\'акет угрожает нам изнутри, и мы осознаем свое шаткое положение в Небесной выси. Мы, Ваятели ветра, должны спасти свой дом и позаботиться о том, чтобы шен\'дорай пережили тяжелые времена. В этом нам поможет наш дар.',70245),
(92596,'ruRU','Высший орден заботится о выживании нашего народа. Мы чтим своих стихийных покровителей, но должны принимать реальность такой, какая она есть. Их больше нет с нами – мы предоставлены сами себе.\r\n\r\nАл\'акет угрожает нам изнутри, а на уязвимое состояние нашего дома нельзя закрывать глаза, но мы потомки высокорожденных Эльдре\'Таласа: мы должны позаботиться о том, чтобы шен\'дорай вновь твердо стояли на ногах. В этом нам поможет наш дар.',70338),
(92597,'ruRU','Чувствуешь? Да? Прекрасно! Ты $gсделал:сделала; первые шаги. С твоими способностями ты сможешь использовать магическую энергию многих мест. Так можно получить разные преимущества – иногда явные, иногда незаметные. Точно не узнаешь, пока не попробуешь. Но это лучшая часть твоего дара... узнавать непознанное.\r\n\r\nЧтобы выжить в эти тяжелые времена, нам надо неустанно стремиться к знаниям... и силе.',70338),
(92598,'ruRU','Небесный взор – как еще одна мышца, которую нужно развивать, если хочешь усилить свой дар. В твоих приключениях наверняка пригодится способность стирать грань между мирами смертных и духов.\r\n\r\nСоветую запомнить то, чему ты $gнаучился:научилась; сегодня. Способность слышать то, о чем говорят духи, может стать ключом к нашему выживанию',70245),
(92640,'ruRU','Отношения между Ваятелями ветра и Высшим орденом сейчас напряженные, но план не удастся без содействия обеих сторон.',70338),
(92642,'ruRU','Ты еще $gжив:жива;? Что ж... Спасибо ветрам за это маленькое чудо.',70338),
(92643,'ruRU','<Сектант явно мертв – его убили ассасины, с которыми вы сразились у входа в дом. Вы наклоняетесь, чтобы осмотреть тело, и замечаете, как что-то поблескивает на свету...>',70338),
(92644,'ruRU','Значит, перебежчик был уже мертв? Печально...\r\n\r\n<Вы отдаете кристалл, который нашли на теле мертвого сектанта.>\r\n\r\nА это уже интересно...',70338),
(92645,'ruRU','Бельгилос мертва? Да хранят тебя четыре ветра, |3-6($c).\r\n\r\nПохоже, мы еще переживем этот бой.',70338),
(92679,'ruRU','<Вы рассказываете Аамелии, что случилось с Альварионом.>\r\n\r\nЧто ж, зато теперь я знаю, что он в Валанааре и в безопасности.\r\n\r\nПослушай, $gнезнакомец:незнакомка;... Мне очень жаль, но мой дуралей зря послал тебя сюда – только погибнешь напрасно. Если в тебе есть хоть капля благоразумия, уходи подобру-поздорову. Это не твоя битва.',70338),
(92682,'ruRU','Я все видела в окно: а ты неплохо $gсправился:справилась; с этими бандитами.',70338),
(92683,'ruRU','Обращаться с этой пыльцой не очень приятно: она везде забивается. Боюсь, ты еще долго будешь вытряхивать ее из штанов. Зато ты очень мне $gпомог:помогла;. Я уже несколько недель собиралась этим заняться, но боялась отойти от дома, пока я тут совсем одна, а вокруг поджидают бандиты.\r\n\r\nТолько не спрашивай, для чего я использую пыльцу. Нужно для всякого... Не бери в голову.',70338),
(92684,'ruRU','Вот это крупные вырезки! Каких же монстров ты там $gзавалил:завалила;?',70338),
(92685,'ruRU','А ты меня $gпослушал:послушала;: маски и правда пропитаны кровью. И славно. Так я точно знаю, что мерзавцам было больно.\r\n\r\nА если серьезно, огромное спасибо за все, что ты $gсделал:сделала;. Я неделями бесцельно скиталась по ферме, будто ожидая приговора. Теперь ко мне возвращается надежда.\r\n\r\nФерау и его негодяи вот-вот будут здесь. Нужно только их встретить. Что скажешь? Останешься со мной до конца?',70338),
(92693,'ruRU','Не могу поверить... все кончено. Мне надо успокоиться. Иначе сердце выпрыгнет из груди.',70338),
(92698,'ruRU','Голем? Он уже несколько десятков лет бродит по этим полям. Кажется, с тех пор как ушли элементали воздуха. Альварион предположил, что он перевозил урожай на рынок или помогал ухаживать за скотом, когда здесь был большой сад. Но с тех пор прошла уже тысяча лет.\r\n\r\nВ древние времена таких големов поддерживали Ваятели ветра. Мы хотели подать запрос, чтобы те пришли и осмотрели его, но так и не собрались. В последнее время мы просто не обращаем на него внимания.',70338),
(92699,'ruRU','Добро пожаловать. Ратирил отправил мне магическое послание – сообщил о тебе и о том, что у тебя есть потенциал.\r\n\r\nТеперь, когда я вижу тебя своими глазами, мне ясно, почему он предложил тебе встретиться со мной. У тебя ярко выраженная чародейская аура. Среди нас осталось мало тех, кому хватает способностей, не говоря уже о воле, делать то, что должно, ради спасения нашего дома. Достанет ли тебе смелости и силы, чтобы помочь Высшему ордену?\r\n\r\nСкоро мы это узнаем.',70338),
(92701,'ruRU','<Читая письмо, Валенния мрачнеет.>\r\n\r\nАонда доверила тебе доставку послания и хорошо о тебе отзывается в нем. Я тоже постараюсь тебе доверять. Прежде чем продолжить разговор, мне нужно посоветоваться с теми немногими миротворцами, что еще остались со мной, и разработать план на случай нападения культа. Отдохни пока в Валанааре.\r\n\r\nЕсли будешь искать себе занятие, многим горожанам, скорее всего, не помешает помощь $gтакого молодого и сильного искателя:такой молодой и сильной искательницы; приключений, как ты.',70338),
(92703,'ruRU','<Вы рассказываете Альвариону, что произошло в саду. Он слушает со слезами на глазах.>\r\n\r\nДаже не знаю, как тебя отблагодарить, друг мой. Я пришел в Валанаар в поисках надежды и был почти уверен, что мое желание тщетно. Но я нашел героя. Настоящего, как в старых легендах до нашего исхода в Небесную высь.\r\n\r\nЯ не забуду, что ты для нас $gсделал:сделала;, $n. Тебе всегда будут рады в доме Поля Ветров.',70338),
(92709,'ruRU','Теперь ты понимаешь? Возрождение древней магии наших предшественников – ключ к разгадке тайн острова Зефрис и к нашему светлому будущему. Чтобы спасти наш дом, мы должны заново открыть то, что утратили за прошедшие тысячелетия.\r\n\r\nОтвет кроется на Азероте, и маги Кирин-Тора готовы указать нам путь.\r\n\r\nПока мы готовимся к отбытию, поговори с другими членами Высшего ордена в Валанааре. У многих из них есть важные дела, с которыми не помешала бы твоя помощь.',70338),
(92727,'ruRU','<Вы видите на клапане брошенной сумки вкрапления чего-то, похожего на засохшую кровь. Разглядывая пятна, вы также замечаете на клапане вышивку с именем: "Филлион Огненная Дымка".>',70338),
(92741,'ruRU','Сколько когтей – вот это, я понимаю, улов! Мне уже не терпится их изучить.\r\n\r\nБлагодарю тебя за службу Высшему ордену, |3-6($c).',70338),
(92834,'ruRU','Высший орден гордится своим прагматизмом и логикой, а логика показывает, что избежание конфликта и напрасных потерь – наиболее разумное решение в большинстве ситуаций.\r\n\r\n<Глаза Элаадрина загораются и искрятся от чародейской энергии.>\r\n\r\nОднако сектанты приняли нашу осмотрительность за слабость, и они даже не представляют, как серьезно поплатятся за эту ошибку.',70338),
(92840,'ruRU','Будь моя воля, сегодня не пролилось бы ни капли крови Ваятелей Ветра. Но вина за эту бессмысленную стычку лежит только на них. Мы лишь хотели собрать сведения, а они прибегли к насилию.\r\n\r\nК сожалению, молва уже разошлась, и Ваятели Ветра вовсю кричат о "побоище". Они не посмеют напасть на нас здесь, в Валанааре, но точно не забудут о случившемся.\r\n\r\n$n, ты $gоказал:оказала; огромную услугу Высшему ордену. Благодарю.',70338),
(92849,'ruRU','С... спасибо, $gнезнакомец:незнакомка;. Я уже возвращался в Валанаар, когда надо мной вдруг возникла большая тень. Я обернулся и увидел, как с неба на меня мчится огромный и ужасный зверь. Я побежал, но что-то тут же ударило меня, и все потемнело.\r\n\r\nСкажу без преувеличения: если бы ты сейчас не $gподошел:подошла;, я бы сгинул в пасти этого зверя и его детенышей.',70338),
(92850,'ruRU','Еще раз благодарю тебя, $n.',70338),
(92860,'ruRU','Жаль, что так вышло с Белатааном. Ты, наверное, не $gзнал:знала;, но я его двоюродная сестра. Он был хорошим магом и верой и правдой служил нашему острову. Мы за него отомстим.\r\n\r\nВижу, ты уже $gготов:готова; оказать поддержку. Идем. Надо обсудить сложившуюся ситуацию.',70338),
(92880,'ruRU','<Валенния с видимым облегчением выслушивает ваш отчет о ситуации у восточной башни.>\r\n\r\nХвала ветрам...',70338),
(92881,'ruRU','Есть одно маленькое дело, для решения которого как раз нужна помощь такого искателя приключений, как ты.',70338),
(92947,'ruRU','Нам многого стоило сюда пробиться, но это еще не конец.',70338),
(93036,'ruRU','Приветствую, дитя. Я Сания Серебряный Поток, жрица ордена Ал\'акет. Хочешь узнать больше о нашем повелителе Ал\'акире Владыке Ветра?\r\n\r\nЗа его столом всегда найдется место для праведных и покаянных.',70338),
(93065,'ruRU','Мы готовы выступать.',70338),
(93089,'ruRU','Меня радует, что верховный старейшина Песня Теней благословил нашу экспедицию. Мы разгромили секту и подготовили все необходимое, – думаю, пора в путь.\r\n\r\nТрудяга Ансирем подготовил работающий неборез, который доставит нас с Зефриса в город Даларан. Мы все проверили как только могли – пора авангарду отправляться.',70338),
(93159,'ruRU','...Вот и все, что я могу об этом рассказать. Я был... гм... где-то еще, а потом оказался тут. И теперь я тут со своими друзьями и своими вещами. Вещами... которые сделал сам. Это все, что мне нужно. Ну, я так думаю, во всяком случае.\r\n\r\nНо вот что хочу сказать, это здорово – говорить с кем-то, кто может тебе ответить. Лесные духи стараются отвечать, но они умеют только петь. Это тоже по-своему мило, но интеллектуальная беседа не получается.',70338),
(93160,'ruRU','Спасибо, $gнезнакомец:незнакомка;! Я их поджарю, будет пальчики оближешь. \r\n\r\nОдин момент, сейчас все будет.',70338),
(93165,'ruRU','Превосходно. Уничтожение этих сектантов – безусловное благо. Надеюсь, теперь-то они поймут, что с Когтем Ночи лучше не связываться и память у нас долгая.\r\n\r\nПолагаю, что у тебя свои счеты с этой сектой, и ты еще не раз с ними столкнешься. Если добудешь еще их уши, неси сюда.',70338),
(93172,'ruRU','Спасибо, $gнезнакомец:незнакомка;.',70338),
(93317,'ruRU','Клянусь ветром, до чего чудесное мясо!\r\n\r\nОгромное спасибо, |3-6($c).',70338),
(93318,'ruRU','Нам хватает хлопот с сектантами и бандитами нагорья – гигантский лисвен, терроризирующий мирных жителей, нам точно не нужен. Ты $gсовершил:совершила; благородный поступок. Вот обещанная награда.',70338),
(93319,'ruRU','Спасибо, |3-6($c). Этого нам пока должно хватить. Но если мы не наладим снабжение в ближайшем будущем, украденные ветрокамни будут меньшей из наших проблем.',70338),
(93320,'ruRU','Пока что нам удается сдерживать врагов, но их больше, чем нас, а наши бойцы начинают уставать. Мы должны пересилить противника, и поскорее.',70338),
(93459,'ruRU','Вот твоя обещанная награда.',70338),
(93461,'ruRU','Значит, ты $gпоговорил:поговорила; с Ратирилом? Отлично. Отношения у Высшего ордена и Ваятелей ветра сейчас напряженные, но здесь, в Шен\'даре, они сдерживают свой конфликт в определенных рамках. По крайней мере в деревне. О том, что происходит в степях, знают только ветры.\r\n\r\nТак, с этим мы закончили... Похоже, ты ищешь себе занятие. У меня есть пара предложений, если ты не прочь немного потрудиться.',70338),
(93552,'ruRU','Спасибо тебе большое. Мы, эльфы, тесно связаны с магией, и эти ветрокамни становятся все ценнее по мере того как магия, наполняющая наши земли благодаря опорным столпам, продолжает рассеиваться.\r\n\r\nНо земля богата не только ветрокамнями. Вот, возьми одно из этих руководств.',70338),
(93835,'ruRU','Я велел нескольким оставшимся магам проследить за тем, чтобы Валенния и ее бойцы тоже смогли уйти. Сейчас она должна отдыхать у верховного старейшины Песни Теней.\r\n\r\nАнсарем был вынужден вернуться на Азерот, но мы с ним успели обсудить дальнейшие шаги Высшего ордена. Сегодня мы выжили, но теперь Зефрис опасно уязвим, и мы должны составить план на будущее.',70338),
(93926,'ruRU','<Труп достаточно свежий – смерть настигла несчастного недавно. Судя по ожогам на коже, это дело рук сектантов, владеющих магией бури.>',70338),
(93927,'ruRU','Значит, все они мертвы. Да разразит буря этих проклятых сектантов!\r\n\r\nХотя тебе удалось избавиться от жреца и остановить их в башне, должна признать, что теперь меня еще сильнее беспокоят твои слова об их махинациях со столпом. У них был огромный запас ветрокамней, а значит, им требовалось колоссальное количество энергии.\r\n\r\nКакова же их цель? Ритуал со столпом, нападение на деревню... Для чего все это?',70338),
(93948,'ruRU','Какая ужасная новость... Мой племянник мертв. Спасибо, что $gпринес:принесла; этот перстень.\r\n\r\nНечасто такие молодые и способные шен\'дорай заглядывают к нам с нагорий. Если тебе нужна работа, поговори с Валеннией Штормовой Кулак, капитаном миротворцев в Валанааре. Нам сейчас пригодится любая помощь.',70338),
(93949,'ruRU','Я не сомневаюсь, что в Валанааре их еще много, но с каждым зачарованным небопрыгом, которого мы растоптали, наш город становится немного безопаснее.',70338),
(93951,'ruRU','Украшения для волос могут показаться показным излишеством. Однако даже в такие времена нужно позволять себе маленькие радости.\r\n\r\nЕсли мое творение принесет кому-то радость, то день пройдет не зря. Спасибо, что $gпринес:принесла; мне эти перья – с твоей помощью я смогу порадовать жителей Зефриса.',70338),
(93958,'ruRU','<Валенния серьезно ранена.>',70338),
(94006,'ruRU','Итак, ты хочешь пойти по пути когтя, дитя? Давай поговорим.',70338),
(94369,'ruRU','<Талаанис Песня Теней внимательно слушает ваш рассказ о том, что произошло над святилищем Акира, и план Элаадрина покинуть остров Зефрис.>\r\n\r\nМне надо обдумать это все. Что хорошо – мы избавились от Лортуны и обезглавили секту. В наш дом еще никто не вторгся, и, зная повелителей элементалей, могут пройти еще многие годы и даже десятилетия, прежде чем Ал\'акир наконец обратит на нас внимание.\r\n\r\nНам есть чего бояться, но также есть и повод для радости.',70338),
(94411,'ruRU','Столкновения между братьями и сестрами лишь ослабляют шен\'дорай, но иногда нужно действовать решительно, чтобы предотвратить еще большую беду.\r\n\r\nМагов Высшего ордена совсем не волнуют последствия их вмешательства. Силы, хранящие наш остров, хрупки и уязвимы – один необдуманный поступок, и наш дом будет уничтожен.',70291),
(94413,'ruRU','Иногда сложно разграничить слепой фанатизм культа Ал\'акет и упрямство Ваятелей ветра, отвергающих перемены.\r\n\r\nЕсли бы они и правда верили, что ветра направят нас, то чувствовали бы, куда дуют эти ветра, и следовали бы за ними, а не против них.',70338),
(94414,'ruRU','Благодарю, что $gразделил:разделила; со мной этот момент. Я продолжу наблюдать за рощей и размышлять о том, что стало с нашими землями.',70338),
(94484,'ruRU','Как хорошо, что наше послание добралось до Лотелума. Погоди, а где остальные бойцы? Тебя же не отправили $gодного:одну;?\r\n\r\n<Элегаэль бледнеет, когда вы пересказываете ей разговор с Лотелумом.>\r\n\r\nЗначит, послание не дошло. Тогда мы и вправду в тяжелом положении.\r\n\r\nПохоже, придется справляться своими силами. Время дорого.',70338),
(94485,'ruRU','<Элегаэль берет у вас липкий мох, устало улыбаясь.>\r\n\r\nСпасибо, $n, ты славно $gпотрудился:потрудилась;. Это как раз то, что нам нужно.',70338),
(94486,'ruRU','Благодарю. Я использую каждое перо, чтобы их жертва не была напрасной.',70338),
(94487,'ruRU','<Элегаэль тревожно смотрит на окровавленные трофеи.>\r\n\r\nСтолько жизней потеряно, столько потенциала было у этих молодых шен\'дорай. Спасибо, что $gпринес:принесла; эти реликвии, |3-6($c).\r\n\r\nЯ сохраню их, а потом отнесу верховному старейшине. Он позаботится о том, чтобы они дождались следующего и, возможно, более достойного поколения.',70338),
(94488,'ruRU','<Элегаэль морщится, увидев отрубленную голову, но потом кивает.>\r\n\r\nСпасибо, $n. Как бы ни бушевала во мне ярость, мне было бы сложно убить собрата.\r\n\r\nНе стоит о нем скорбеть. Его невежество и злоба погубили сегодня множество невинных жизней.',70338),
(94489,'ruRU','<Элегаэль бледнеет, когда вы рассказываете о судьбе Йорела и состоянии остальных друидов.>\r\n\r\nНет... Нет! Все куда хуже, чем я...\r\n\r\n<Элегаэль сдерживает слезы и сжимает зубы, натужно рыча.>\r\n\r\nОни заплатят. Они все заплатят! Все, кто якшается с культом Ал\'акет, познают мой гнев! Клянусь...',70338),
(94490,'ruRU','Им был нужен столп? Но зачем? Мы даже не были их целью?\r\n\r\n<Элегаэль продолжает читать, дрожа от гнева.>\r\n\r\nОни убили моих товарищей, потому что мы оказались на пути! Я разорву каждого сектанта собственными клыками! Никто не уйдет отсюда живым.\r\n\r\nПоспеши! Если приказ и правда поступил из Валанаара, вероятно, там прячется предатель. Передай послание Лотелуму в Валанааре и расскажи ему, что произошло.',70338),
(94491,'ruRU','<Лотелум смотрит на вас с неподдельным ужасом, когда вы рассказываете, что произошло в логове друидов.>\r\n\r\nЯ... прошу меня извинить, $n. Дай мне минуту. У меня нет слов, чтобы выразить, что я сейчас чувствую.\r\n\r\nПоистине удручающая новость. Если послание не поддельное, то здесь, в Валанааре, прячется в лучшем случае сообщник сектантов, а в худшем – предатель. Немедленно поставлю в известность верховного старейшину! Я не допущу, чтобы жертва моих товарищей оказалась напрасной.',70338),
(94568,'ruRU','Можно было бы отправить миротворцев на бой с культом, но мы вряд ли одолеем их в открытом бою.\r\n\r\nНам нужен другой подход.',70338),
(94638,'ruRU','Моя боль от утраты огромна, но это было нужно, чтобы сохранить равновесие. Ты $gдоказал:доказала;, что у тебя есть решимость выживать и делать то, что должно, даже если цена ужасна.\r\n\r\nТы молодец, |3-6($c). Благословляю тебя принимать наш облик. Будь лучом надежды для слабых и $gзащитником:защитницей; для нуждающихся.\r\n\r\nИди и познавай путь когтя, дитя.',70338),
(94896,'ruRU','Спасибо, |3-6($c). Мы, беженцы, не забудем твоей доброты. Я прослежу, чтобы эти вещи вернулись к владельцам. Теперь у нас хотя бы будет с чего начать новую жизнь.',70338),
(94897,'ruRU','<Глаза Эаланы наполняются слезами.>\r\n\r\nО, Ресаан, любовь моя... Что же теперь с нами станет? Столько воспоминаний... Кажется, будто наша жизнь вдвоем только начиналась.\r\n\r\nСпасибо, |3-6($c). Как же жестока судьба – я лишилась и дома, и любимого. Но теперь я хотя бы знаю, что с ним произошло.',70338),
(94912,'ruRU','Привет, |3-6($c). Рад встретить собрата-друида из рода небеснорожденных и одним из первых приветствовать тебя на Азероте.\r\n\r\nДумаю, моим друзьям из Круга Кенария есть чему тебя научить, дитя природы.',70425),
(94914,'ruRU','Вижу, ты уже $gосвоил:освоила; форму медведя. Чудесно, чудесно. Ты быстро учишься, молодой друид.',70425),
(94946,'ruRU','А, вот и ты. Чудесно. Нам еще нужно тут обустроиться, так что у тебя есть время все здесь осмотреть. Но постарайся не отходить от города.\r\n\r\nЭти новые земли кажутся безмятежными, но выходить за пределы Даларана без должной подготовки может быть очень опасно.',70338),
(96101,'ruRU','Мы изучили основы, а теперь иди поучись ремеслу у наставников в деревне поблизости. Они даже могут показать, как обустроить лагерь в соответствии с твоей новой профессией.',70338),
(96395,'ruRU','Мой... тан... обрел... покой... Да... покой.\r\n\r\nСпасибо... тебе...\r\n\r\nЯ... отдохну...',70425),
(96403,'ruRU','Вы только поглядите, какая храбрость и предприимчивость! Я дал слово гнома, и ты свою награду честно $gзаслужил:заслужила;!\r\n\r\nТеперь позволь-ка мне взглянуть на добычу... э-э... то есть на найденные реликвии. Мне нужно начать их оценивать... прости, "каталогизировать", чтобы как можно быстрее вернуть на законные места.',70425),
(96638,'ruRU','Рад встрече!',70338),
(96646,'ruRU','С этим ты сможешь разбить лагерь где угодно. Пока ты $gосвоил:освоила; только азы, так что особенно обставить лагерь не получится.\r\n\r\nУчись – и со временем научишься разжигать огонь пожарче и делать разные интересные вещи.\r\n\r\nЕще ты можешь научиться создавать разные полезные вещи в лагере – поговори с другими наставниками профессий, в которых хоть немного разбираешься.',70338),
(97963,'ruRU','Вот, теперь ты можешь создать собственный колодец маны. В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо. Лучше отправляйся куда-нибудь в дикие места.\r\n\r\nА, и помни, что никакого лагеря без костра не получится. Так что сначала придется разжечь костер. Этому тебя может научить почти любой специалист по кулинарии. Если еще не $gозаботился:озаботилась; этим, обратись к кому-нибудь из учителей этой профессии, чтобы освоить азы.',70338),
(97968,'ruRU','Вот, теперь ты можешь создать собственную ароматную свечу. В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо. Лучше отправляйся куда-нибудь в дикие места.\r\n\r\nА, и помни, что никакого лагеря без костра не получится. Так что сначала придется разжечь костер. Этому тебя может научить почти любой специалист по кулинарии. Если еще не $gозаботился:озаботилась; этим, обратись к кому-нибудь из учителей этой профессии, чтобы освоить азы.',70338),
(97971,'ruRU','Вот, теперь ты можешь создать собственный лагерный стул. В городах лагеря лучше не разбивать, а то на тебя будут смотреть косо. Лучше отправляйся куда-нибудь в дикие места.\r\n\r\nА, и помни, что никакого лагеря без костра не получится. Так что сначала придется разжечь костер. Этому тебя может научить почти любой специалист по кулинарии. Если еще не $gозаботился:озаботилась; этим, обратись к кому-нибудь из учителей этой профессии, чтобы освоить азы.',70245),
(98423,'ruRU','Ах да, мой предок Мадоран стал первым королем Стальгорна из рода Бронзобородов после масштабной гражданской войны между кланами Громового Молота, Бронзобородами и кланом Черного Железа. Этот договор был составлен для формального признания окончания боевых действий и закрепления условий мира после победы Бронзобородов в битве за гору.\r\n\r\nКак видишь, Громовые Молоты и Бронзобороды его подписали... а вот дворфы Черного Железа – нет.\r\n\r\nСпасибо, что $gнашел его и принес:нашла его и принесла; мне, |3-6($c).',70425),
(98512,'ruRU','Хорошо, что ты $gвернулся:вернулась; в целости. Те ал\'акеты выглядели как безжалостные головорезы.\r\n\r\nСпасибо за помощь. Я упомяну это в отчете, когда вернусь в Валанаар.',70338),
(99260,'ruRU','Признаю, я страшно рад, что Филлион к нам вернулся. Он частенько не замечает, что творится вокруг. То слишком глубоко задумается, то увлечется книгой...\r\n\r\nСпасибо тебе, |3-6($c).',70338);
INSERT INTO `quest_request_items_locale` (`ID`,`locale`,`CompletionText`,`VerifiedBuild`) VALUES
(79097,'ruRU','$gПринес:Принесла; что-то новенькое в нашу коллекцию?',70338),
(91741,'ruRU','Что у тебя там? Похоже на одну из моих книг.',70338),
(92463,'ruRU','Щетинистых ос нельзя недооценивать. На вид они не особенно опасны, но берегись тех, что покрупнее. Чем больше такая оса, тем она злее!',70245),
(92470,'ruRU','Я прошу от тебя многого, но ты $gдолжен быть готов:должна быть готова; к куда большим опасностям, если хочешь жить ради Зефриса, а не быстро умереть во имя его.',70338),
(92473,'ruRU','Медверы в последнее время стали куда агрессивнее. Интересно, с чего их поведение так изменилось?',70338),
(92485,'ruRU','Приветствую. Я Зитон Среброветрый, хранитель знаний друидов.',70338),
(92515,'ruRU','На самом деле я считаю, что когти прайда довольно милые. Если смотреть на них с безопасного расстояния... и стоя за спиной у кого-нибудь с мечом, конечно же.',70338),
(92550,'ruRU','Как же приятно отвечать этим фанатикам той же агрессией.',70338),
(92551,'ruRU','Эти припасы очень нужны голодным и отчаявшимся небеснорожденным.',70338),
(92553,'ruRU','Какие бы перемены ни пришли на Зефрис, сколько бы неопределенности ни окружало нас, я всегда говорю: нет ничего лучше трубки, набитой сушеным мироцветом, и вкусной сытной еды!',70338),
(92644,'ruRU','А, ты $gвернулся:вернулась;... Но... почему $gодин:одна;?',70338),
(92682,'ruRU','Эти негодяи предают и обворовывают друг друга даже чаще, чем крадут у простого народа. Бьюсь об заклад, если Ферау узнает, что его бандиты самовольно пришли сюда раньше и портят урожай, он убьет их своими руками.',70338),
(92683,'ruRU','Обычно порхательницы безобидны, но они удивят тебя, если их раздразнить.',70338),
(92684,'ruRU','Уже и не вспомню, когда у нас на обед было нормальное мясо... Слишком давно.',70338),
(92685,'ruRU','Может, если ты принесешь мне достаточно масок, я сошью из них покрывало и подарю его Ферау.\r\n\r\n<Аамелия громко смеется.>',70338),
(92701,'ruRU','Письмо от Аонды. Что на уме у этой проныры с нагорья?',70338),
(92741,'ruRU','Обычно члены Высшего ордена не утруждают себя работой, с которой могут справиться простые звероловы или егеря, но когда подобная общественная деятельность ведет к научным открытиям, мы с радостью ею занимаемся.',70338),
(92834,'ruRU','Я нечасто соглашаюсь с Ваятелями Ветра, но они были совершенно правы, когда не стали договариваться с ал\'акетами. Моя попытка решить дело миром стоила жизни моему близком другу, а мне придется жить с этим до конца моих дней.',70338),
(92840,'ruRU','Иногда я не вижу разницы между Ваятелями Ветра и сектантами Ал\'акет. Может, одни чуть агрессивнее других, но они все погрязли в своих ложных верованиях и одинаково опасны, если ничего с этим не делать.\r\n\r\nОни считают, что наше желание изучить Зефрис и лучше понять его магию – это кощунство, подрывающее их устои. Твердолобость Ваятелей делает нашу задачу еще более важной. Если не мы, то кому еще хватит смелости спасти Зефрис?',70338),
(92850,'ruRU','Эти визгуны слишком опасны, чтобы позволять им гнездиться так близко от Валанаара. Но сейчас они наименьшая из наших напастей.',70338),
(93160,'ruRU','Мм-м, тебе понравится, что я приготовлю из этих желудей!',70338),
(93165,'ruRU','Я не успокоюсь, пока не перегрызу глотку последнему сектанту на этом острове.',70338),
(93317,'ruRU','Мясо ветроозерных крабов довольно распространено в наших краях, зато на островах Анвилас и Сироккас оно считалось деликатесом. Раньше, когда ветряные потоки были еще открыты, я наведывалась в Шен\'драмар или Новый Эльдре\'наар, и местные окружали меня толпой, желая его выкупить.\r\n\r\nНо я не была в тех местах уже... очень-очень давно.',70338),
(93318,'ruRU','Мне понадобится доказательство гибели твари – ее голова.',70338),
(93319,'ruRU','Эти воришки, по всей видимости, уже не первый месяц таскают наши припасы. Я просила Аонду собрать бойцов и избавиться от бандитов раз и навсегда, но она не захотела оставлять деревню без защиты тех немногих миротворцев, что у нас еще остались.\r\n\r\nИ я ее понимаю: сектантов в деревне Фалаат, что на юге, становится все больше.',70338),
(93459,'ruRU','<Вайн кивает вам.>',70338),
(93552,'ruRU','Приветствую, |3-6($c).',70338),
(93927,'ruRU','Какие вести от западного дозора?',70338),
(93948,'ruRU','Что это у тебя? О... о нет.',70338),
(93951,'ruRU','$gПринес:Принесла; мне что-нибудь красивое?',70338),
(94485,'ruRU','Ты $gнашел:нашла; девичьи слезы?',70338),
(94486,'ruRU','Мне жаль просить тебя убить молодых визгунов, но так будет лучше: они стали слишком агрессивными. У нас и без того достаточно проблем.',70338),
(94487,'ruRU','Я заставлю сектантов заплатить за каждую каплю пролитой крови друидов.',70338),
(94488,'ruRU','Неужели ты и правда совсем не ценишь жизни наших собратьев, Хаалиен?',70338),
(94896,'ruRU','У многих нет ничего, кроме одежды, что была на них в момент бегства. Любые пожитки станут для нас ценной находкой.',70338),
(94897,'ruRU','Есть вести о Ресаане? Прошу тебя, |3-6($c), поторопись: после всего, что случилось, ожидание так мучительно.',70338),
(96403,'ruRU','<Том рассеянно потирает руки, глядя на вас.>',70425),
(97291,'ruRU','Так трогательно, когда заблудшая овечка возвращается в стадо, не правда ли?',70338),
(98423,'ruRU','Что ты $gпринес:принесла; из глубин, |3-6($c)?',70425),
(99191,'ruRU','В настоящее время Высший орден принимает пожертвования в виде шерстяной ткани.\r\n\r\nСделай подношение в размере шестидесяти отрезов – именно столько нам сейчас требуется – и Орден в полной мере оценит твою щедрость.$B$BЕсли у тебя есть шестьдесят отрезов шерстяной ткани и ты $gготов:готова; принести их в дар, я с радостью приму их прямо сейчас.',70425);
